(function(){const query=new URLSearchParams(location.search);if(query.get('embed')==='1'){document.body.classList.add('embedded');if(query.get('view')==='practice')document.body.classList.add('practice-only')}if(query.get('lang')==='en'&&lang!=='en'){lang='en';translate()}let previous=0;function notify(){const height=Math.ceil(document.body.getBoundingClientRect().height)+8;if(window.parent!==window&&height!==previous){previous=height;window.parent.postMessage({type:'iyal-height',height},location.origin)}}new ResizeObserver(notify).observe(document.body);window.addEventListener('load',notify);notify()})();
